    81		m_running = true;
    82	
    83		int cnt = 0;
    84	
    85		m_wait = true;
    86		m_timer.start();
    87	
    88		while(!m_abort) {
    89			if(!m_trigger.wait(500)) {
    90				break;
    91			}
    92	
    93			int n = m_buffer->size();
    94			while(n) {
    95				chunk c;
