    97					trace(1, "%s: error: failed to pop data", __PRETTY_FUNCTION__);
    98					break;
    99				}
   100	
   101				if(m_wait) {
   102					if((m_conf.start_delay != 0) && !m_timer.lapsed_ms(m_conf.start_delay)) {
   103						m_buffer->clear();
   104						break;
   105					}
   106	
   107					m_wait = false;
   108	
   109					m_alarm = std::make_unique<alarm_manager>();
   110					if(m_alarm->init(m_alarm_conf) != 0) {
   111						break;
   112					}
   113	
   114					m_stream = std::make_unique<stream>(this);
   115					if(m_stream->init(c.ts, m_alarm.get()) != 0) {
   116						break;
   117					}
   118	
   119					trace(1, "%s: analyze start", __PRETTY_FUNCTION__);
   120				}
   121	
   122				m_stream->push(c.ts, c.data, c.size);
   123				m_stream->update_events(c.ts, m_conf.timeout);
   124	
   125				if((ts == 0) || ((c.ts - ts) >= 1e9)) {
   126					m_stream->update_stats(c.ts, cnt == 0);
   127	
   128					ts = c.ts;
   129					cnt = (cnt + 1) % m_conf.stats;
   130				}
   131				n--;
   132			}
   133		}
   134	
   135		m_running = false;
   136	}
