const { spawn } = require("child_process");
const { EventEmitter } = require("events");
const fs = require("fs");
const yaml = require("js-yaml");
const { getAdjustedRcvBufSize } = require("../utility/LocalMulticastStream.js");
const { getMulticastPort } = require("../utility/getMulticastPort.js");
const { getPacketSize } = require("../utility/config.js");
const { sendStatusLogMessage, MHLOG } = require("../utility/notice.js");
const { checkLicense } = require("../utility/license.js");
const { MonitoringPointType } = require("../utility/license.js");
const { getEnvVar, isEnable } = require("../utility/config.js");
const { getMaskSeconds, isEnabled: isMaskEnabled } = require("../utility/initialLogMask.js");

const SOURCE_TSM_CONF = "/usr/local/etc/tsa/tsm.conf";
const RUNTIME_TSM_CONF = "/tmp/tsm.runtime.conf";
const TSM_START_DELAY_FLOOR_MS = 5000;

/**
 * 初期マスクが有効なときに、tsm.conf の start_delay を上書きした
 * runtime conf を /tmp に生成する。無効時や生成失敗時は null を返す。
 *
 * @returns {string|null} 生成した runtime conf のパス、または null
 */
function generateTsmRuntimeConfIfNeeded() {
  if (!isMaskEnabled()) {
    return null;
  }
  const maskSec = getMaskSeconds();
  const desiredStartDelayMs = Math.max(TSM_START_DELAY_FLOOR_MS, maskSec * 1000);
  try {
    const sourceText = fs.readFileSync(SOURCE_TSM_CONF, "utf8");
    const doc = yaml.load(sourceText) || {};
    if (!doc.analyze || typeof doc.analyze !== "object") {
      doc.analyze = {};
    }
    doc.analyze.start_delay = desiredStartDelayMs;
    const out = yaml.dump(doc);
    fs.writeFileSync(RUNTIME_TSM_CONF, out, "utf8");
    console.log(
      `[初期マスク] tsm.runtime.conf を生成しました start_delay=${desiredStartDelayMs}ms (path=${RUNTIME_TSM_CONF})`
    );
    return RUNTIME_TSM_CONF;
  } catch (err) {
    console.error(
      "[初期マスク] tsm.runtime.conf の生成に失敗しました。既定の tsm.conf を使用します:",
      err
    );
    return null;
  }
}

// tsmプロセス
let tsmProcess = null;
const tsmEvents = new EventEmitter();
async function RunTsm(retryCount = 0) {
  // 初回ライセンスチェック
  const initPoint = await checkLicense(MonitoringPointType.TS, true);

  if (!(initPoint > 0)) {
    if (initPoint === null) {
      await sendStatusLogMessage(MHLOG.TSMON_LICENSE_ERROR);
    } else {
      console.error("ポイント不足の為、TS監視を起動できません。");
      await sendStatusLogMessage(MHLOG.TSMON_START_FAIL_LOW_POINTS);
    }

    // 10分後に再チェック
    setTimeout(() => RunTsm(), 1000 * 60 * 10);
    return;
  }

  // ライセンスOKの場合
  await sendStatusLogMessage(MHLOG.TSMON_LICENSE_OK);

  // 1時間に1回ライセンスチェック
  setInterval(
    async () => {
      const point = await checkLicense(MonitoringPointType.TS, true);

      // ライセンスエラーの場合
      if (point === null) {
        await sendStatusLogMessage(MHLOG.TSMON_LICENSE_ERROR);
        process.exit(1);
      }

      if (point > 0) {
        console.log(`残りTSMONpt: ${point}`);
        await sendStatusLogMessage(MHLOG.REMAINING_POINTS_NOTIFY, {
          TSMONP: point,
        });
      } else {
        console.error(`残りTSMONpt: ${point} - TS監視を終了します。`);
        await sendStatusLogMessage(MHLOG.TSMON_STOP_LOW_POINTS);
        process.exit(1);
      }
    },
    1000 * 60 * 60
  );

  try {
    const env = Object.create(process.env);
    env.LD_LIBRARY_PATH = "/usr/lib64";
    env.GCONV_PATH = "/usr/local/lib/gconv/aribb24${GCONV_PATH:+:$GCONV_PATH}";

    // tsmを起動
    const DEFAULT_RCVBUF_SIZE = 32 * 1024 * 1024; // 32MB
    // 初期マスクが有効なときは runtime conf を生成して渡す
    const runtimeConfPath = generateTsmRuntimeConfIfNeeded();
    const tsmArgs = [
      "/app/utility/tsanalyze/tsm.sh",
      getMulticastPort(),
      getPacketSize(),
      getAdjustedRcvBufSize(DEFAULT_RCVBUF_SIZE),
    ];
    if (runtimeConfPath) {
      tsmArgs.push(runtimeConfPath);
    }
    tsmProcess = spawn("sh", tsmArgs, { env });
    console.log("[tsm]起動しました。");
    await sendStatusLogMessage(MHLOG.TSMON_START);

    // tsmの標準出力を出力
    tsmProcess.stdout.on("data", data => {
      console.log(`[tsm]: ${data.toString()}`);
    });

    // tsmの標準エラー出力を出力
    tsmProcess.stderr.on("data", data => {
      console.error(`[tsm]: ${data}`);
    });

    // tsmの終了を検知
    tsmProcess.on("exit", async (code, signal) => {
      try {
        await checkLicense(MonitoringPointType.TS, false);
      } catch (error) {
        console.error("ライセンス通知に失敗", error);
      }

      if (code !== null) {
        console.log(`tsmスクリプトが終了しました。終了コード: ${code}`);
        await sendStatusLogMessage(MHLOG.TSMON_STOP, {
          code: code,
        });
      } else {
        console.log(`tsmスクリプトがシグナルにより終了しました。シグナル: ${signal}`);
        await sendStatusLogMessage(MHLOG.TSMON_STOP, {
          signal: signal,
        });
      }
      // 正常終了ではない場合、再送信を試みる
      if (code !== 0 && signal !== "SIGINT" && signal !== "SIGTERM") {
        if (retryCount < 5) {
          setTimeout(
            () => RunTsm(retryCount + 1),
            1000 * Math.pow(2, retryCount) // リトライ回数の二乗秒でリトライ
          );
        } else {
          console.error("リトライ回数を超えたので終了します。");
          process.exit(1);
        }
      }
      tsmEvents.emit("exit");
    });
    return true;
  } catch (err) {
    await checkLicense(MonitoringPointType.TS, false);
    console.error(err);
    tsmEvents.emit("exit");
  }
  return true;
}

/**
 * tsmプロセスを終了する
 */

async function StopTsm(signal = "SIGINT") {
  console.log("[tsm]停止します。");
  if (tsmProcess !== null) {
    return new Promise(resolve => {
      // exit ハンドラーの処理完了イベントを待機
      tsmEvents.once("exit", () => {
        resolve();
      });

      tsmProcess.kill(signal);
      tsmProcess = null;
    });
  }
}
