 */
function generateTsmRuntimeConfIfNeeded() {
  if (!isMaskEnabled()) {
    return null;
  }
  const maskSec = getMaskSeconds();
  const desiredStartDelayMs = Math.max(TSM_START_DELAY_FLOOR_MS, maskSec * 1000);
  try {
    const sourceText = fs.readFileSync(SOURCE_TSM_CONF, "utf8");
    const doc = yaml.load(sourceText) || {};
    if (!doc.analyze || typeof doc.analyze !== "object") {
      doc.analyze = {};
    }
    doc.analyze.start_delay = desiredStartDelayMs;
    const out = yaml.dump(doc);
    fs.writeFileSync(RUNTIME_TSM_CONF, out, "utf8");
    console.log(
