/**
 * initialLogMask モジュールのテストケース
 */

const assert = require("assert");
const { test } = require("node:test");

// 環境変数を保存するためのバックアップ
const originalEnv = { ...process.env };

function resetEnv() {
  process.env = { ...originalEnv };
}

// モジュールキャッシュを毎回クリアして読み直す（モジュールロード時の評価を再現するため）
function loadModule() {
  delete require.cache[require.resolve("../utility/initialLogMask.js")];
  return require("../utility/initialLogMask.js");
}

test("INITIAL_LOG_MASK_SEC 未設定 → getMaskSeconds は 0、isEnabled は false", () => {
  resetEnv();
  delete process.env.INITIAL_LOG_MASK_SEC;
  const m = loadModule();
  assert.strictEqual(m.getMaskSeconds(), 0);
  assert.strictEqual(m.isEnabled(), false);
});

test("INITIAL_LOG_MASK_SEC=0 → 機能無効", () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "0";
  const m = loadModule();
  assert.strictEqual(m.getMaskSeconds(), 0);
  assert.strictEqual(m.isEnabled(), false);
});

test("INITIAL_LOG_MASK_SEC=1 → 1秒マスク有効", () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "1";
  const m = loadModule();
  assert.strictEqual(m.getMaskSeconds(), 1);
  assert.strictEqual(m.isEnabled(), true);
});

test("INITIAL_LOG_MASK_SEC=60 → 60秒マスク有効", () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "60";
  const m = loadModule();
  assert.strictEqual(m.getMaskSeconds(), 60);
  assert.strictEqual(m.isEnabled(), true);
});

test("INITIAL_LOG_MASK_SEC=61 → 範囲外で 0 にフォールバック", () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "61";
  const m = loadModule();
  assert.strictEqual(m.getMaskSeconds(), 0);
  assert.strictEqual(m.isEnabled(), false);
});

test("INITIAL_LOG_MASK_SEC=-1 → 範囲外で 0 にフォールバック", () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "-1";
  const m = loadModule();
  assert.strictEqual(m.getMaskSeconds(), 0);
});

test('INITIAL_LOG_MASK_SEC="abc" → 非整数で 0 にフォールバック', () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "abc";
  const m = loadModule();
  assert.strictEqual(m.getMaskSeconds(), 0);
});

test('INITIAL_LOG_MASK_SEC="3.5" → 非整数で 0 にフォールバック', () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "3.5";
  const m = loadModule();
  assert.strictEqual(m.getMaskSeconds(), 0);
});

test("startInitialMask 未呼び出し: isInitialMaskActive は false", () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "1";
  const m = loadModule();
  assert.strictEqual(m.isInitialMaskActive(), false);
});

test("startInitialMask 直後: isInitialMaskActive は true", () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "1";
  const m = loadModule();
  m.startInitialMask();
  assert.strictEqual(m.isInitialMaskActive(), true);
});

test("N+0.2秒後: isInitialMaskActive は false、onExpire が1回呼ばれる", async () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "1";
  const m = loadModule();
  let expireCount = 0;
  m.startInitialMask(() => {
    expireCount++;
  });
  await new Promise(resolve => setTimeout(resolve, 1200));
  assert.strictEqual(m.isInitialMaskActive(), false);
  assert.strictEqual(expireCount, 1);
});

test("startInitialMask を2回呼んでも onExpire は1回のみ", async () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "1";
  const m = loadModule();
  let expireCount = 0;
  m.startInitialMask(() => {
    expireCount++;
  });
  m.startInitialMask(() => {
    expireCount++;
  });
  await new Promise(resolve => setTimeout(resolve, 1200));
  assert.strictEqual(expireCount, 1);
});

test("無効時(INITIAL_LOG_MASK_SEC=0): startInitialMask は noop で isInitialMaskActive は常に false", () => {
  resetEnv();
  process.env.INITIAL_LOG_MASK_SEC = "0";
  const m = loadModule();
  assert.strictEqual(m.isInitialMaskActive(), false);
  m.startInitialMask(() => {
    throw new Error("無効時は onExpire が呼ばれてはならない");
  });
  assert.strictEqual(m.isInitialMaskActive(), false);
});
