json app::load_alarm_config(const std::string &conf_path) {
	json conf;

	YAML::Node root = YAML::LoadFile(conf_path);

	{
		YAML::Node node_common = root["common"];
		if(node_common) {
			conf["common"]["retention_ms"] = node_common["retention"].as<int>() * 1000;
		}
	}

	{
		YAML::Node node_etr290 = root["etr290"];
		for(auto &&item : node_etr290) {
			conf[item["item"].as<std::string>()]["enable"] = item["enable"].as<bool>();
			conf[item["item"].as<std::string>()]["mask"] = json::array();

			YAML::Node mask = item["mask"];
			if(mask) {
				for(auto &&pid : mask) {
					conf[item["item"].as<std::string>()]["mask"].push_back(pid.as<int>());
				}
			}
		}
	}

	{
		YAML::Node node_etr290_24 = root["etr290_24"];
		conf["pcr_accuracy_error_bitrate"]["numerator"]   = node_etr290_24["bitrate"].as<double>();
		conf["pcr_accuracy_error_bitrate"]["denominator"] = 1;
	}

	{
		if(root["etr290_16"]) {
			YAML::Node node_etr290_16 = root["etr290_16"];
			for(auto &&item : node_etr290_16) {
				uint16_t pid      = item["pid"].as<uint16_t>();
				uint64_t interval = item["interval"].as<uint64_t>();

				json j;
				j["pid"]    = item["pid"].as<uint16_t>();
				j["period"] = item["interval"].as<uint64_t>();
				conf["pid_list"].push_back(j);
			}
		}
	}

	return conf;
}

