inline
void depacketizer<Tds, Tpd>::reset() {
	m_ts_packet_size = 0;
	m_total_cc_error_num = 0;
	m_packet_unlatch_num = 0;
	::memset(m_last_continuity_counter, 0xFF, sizeof(m_last_continuity_counter)); // -1 に初期化
	::memset(m_cc_error_num, 0, sizeof(m_cc_error_num));

	m_buffer_used = 0;
	m_part_ts = 0;

	m_packet_detector.reset();
}

template<typename Tds, typename Tpd>
inline
void depacketizer<Tds, Tpd>::set_latch_count(size_t latch_count) {
	m_packet_latch_count = latch_count;
	m_packet_detector.set_latch_count(latch_count);
}

template<typename Tds, typename Tpd>
inline
void depacketizer<Tds, Tpd>::set_unlatch_count(size_t unlatch_count) {
	m_packet_unlatch_count = unlatch_count;
}

template<typename Tds, typename Tpd>
inline
bool depacketizer<Tds, Tpd>::is_cc_error_detected() const{
	return 0 != m_total_cc_error_num;
}

template<typename Tds, typename Tpd>
inline
bool depacketizer<Tds, Tpd>::is_cc_error(mpeg2ts::pid_t pid) const {
	return m_cc_error_num[pid & 0x1FFF];
}

template<typename Tds, typename Tpd>
inline
int depacketizer<Tds, Tpd>::get_cc_error_count(mpeg2ts::pid_t pid) const {
	return m_cc_error_num[pid & 0x1FFF];
}

