function loadLicenseManagerConf() {
  if (!fs.existsSync("/tmp/secret.yaml") || fs.lstatSync("/tmp/secret.yaml").isDirectory()) {
    console.error("エラー: APIキーが見つかりません。");
    return null;
  }

  const file = fs.readFileSync("/tmp/secret.yaml", "utf8");
  const secret = yaml.load(file);
  return secret?.license_manager;
}

async function checkLicense(pointType, is_on) {
  const conf = loadLicenseManagerConf();
  const data = {
    point_type_id: pointType,
    source_id: getEnvVar("SOURCE_ID", ""),
    is_on: is_on,
  };
  const options = {
    headers: {
      "x-api-key": conf.api_key,
      "Content-Type": "application/json",
    },
    httpsAgent: proxyAgent,
    proxy: false, // `axios`のデフォルトプロキシ設定を無効化
  };
  try {
    const res = await axios.post(`${conf.url}/api/point/element`, data, options);
    const license = res.data;
    console.log(`残り${pointType}: ${license.remaining_point}`);
    if (license.remaining_point <= 0) {
      return false;
    } else {
      return license.remaining_point;
    }
  } catch (error) {
    if (error.response && error.response.status !== 200) {
      console.error(
        `ライセンス認証エラー: POST ${`${conf.url}/api/point/element`} - x-api-key:${
          conf.api_key
        } Body:${JSON.stringify(data)} - Code ${error.response.status} ${
          error.response.data.message
        }`
      );
      if (error.response.status === HTTP_STATUS_POINT_SHORTAGE) {
        return false;
      }
      return null;
    }
    throw error;
  }
}

